","new_string":"import { revalidateTag } from 'next/cache'
import { getProducts } from '../lib/products'

export default async function Page() {
  const products = await getProducts()

  async function syncLatestCatalog() {
    'use server'
    revalidateTag('products', 'max')
  }

  return (
    <main>
      <h1>Product catalog</h1>
      <p>Browse current product data. Changes from ERP/PIM may take a moment to appear after a sync.</p>
      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>
      <table>
        <caption>Products</caption>
        <thead>
          <tr>
            <th scope="col">Product</th>
            <th scope="col">Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.name}</td>
              <td>${product.price.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}
"}

